{
  "version": "1.0",
  "source": "generated",
  "locked_predefined_design": false,
  "study_type": "Mixed Methodology - Usage & Attitude, Learner Experience, Churn/Exit, Competitive, and Feature Prioritization",
  "research_design": {
    "design": "linear",
    "stimulus_count": 0,
    "cells": [],
    "rotation": "none",
    "justification": "The brief specifies a linear modular questionnaire with role-based routing and no discrete concepts, prototypes, screens, or competing assets. MaxDiff is conditional on receiving at least five defined improvement options and is not a stimulus-cell design."
  },
  "business_goal": "Determine which learner-experience, content, motivation, feedback, technology, and journey problems LearnSphere should address first to increase sustained engagement, course completion, return usage, and recommendation. Results will set the next product-release priorities, identify recoverable inactive learners and win-back actions, and determine whether LearnSphere has sufficient evidence and capabilities for certification or institutional-partnership expansion.",
  "questionnaire_intent": "Use a three-phase funnel: concise eligibility and lifecycle screening, a core of behavioural and experience diagnosis, and a closing phase covering stakeholder success criteria, future intent, prioritisation, advocacy, and the final improvement recommendation. Role and lifecycle routing prevents current learners, inactive learners, potential users, parents, educators, and administrators from being combined into misleading scores.",
  "survey_objectives": [
    {
      "objective": "Measure recent learning frequency, course progress, completion status, and stopping points among current and former LearnSphere learners to identify where engagement pauses or ends.",
      "importance": "This establishes the behavioural basis for completion and churn analysis rather than relying only on stated satisfaction."
    },
    {
      "objective": "Measure journey-stage experience and friction from discovery and onboarding through course participation, progress tracking, interruption, and resumption.",
      "importance": "LearnSphere needs to identify the precise stages requiring product or process improvement."
    },
    {
      "objective": "Measure content relevance and the usefulness of instructional formats such as videos, quizzes, practice, plans, dashboards, and reminders.",
      "importance": "This distinguishes content and learning-design problems from motivation, time, or technology barriers."
    },
    {
      "objective": "Measure primary and secondary engagement barriers, including content, time, motivation, navigation, technology, value, trust, and competition barriers.",
      "importance": "Barrier segmentation is needed to match users with appropriate product fixes, content changes, or interventions."
    },
    {
      "objective": "Measure awareness and perceived value of AI recommendations, adaptive learning, feedback, reminders, progress visibility, social learning, and gamification among respondents with relevant exposure.",
      "importance": "The business must distinguish feature awareness from trusted, useful mechanisms that create genuine learning momentum."
    },
    {
      "objective": "Measure usage of competing platforms, offline alternatives, creator-led content, coaching, institutional systems, and peer-learning routes, including their share of learning time.",
      "importance": "This reveals where learning time is diverted and where competitive switching pressure originates."
    },
    {
      "objective": "Measure continuation, return, trial, win-back, and recommendation intent across relevant lifecycle and stakeholder groups.",
      "importance": "These indicators quantify retention, acquisition, recoverability, and advocacy potential."
    },
    {
      "objective": "Measure role-specific success criteria and evidence requirements among parents or guardians, teachers or instructors, and academic administrators.",
      "importance": "These requirements inform household adoption, educator use, institutional readiness, and partnership decisions."
    },
    {
      "objective": "Prioritise the improvement area most likely to increase engagement, completion, return usage, and recommendation, with a conditional forced-trade-off or MaxDiff exercise if a validated feature list is supplied.",
      "importance": "LearnSphere needs a practical roadmap signal instead of an undifferentiated list of highly rated improvements."
    },
    {
      "objective": "Measure likelihood to recommend and the most important improvement respondents want LearnSphere to make.",
      "importance": "Advocacy and an open-ended recommendation provide a benchmark and reveal unmet needs not captured in predefined categories."
    }
  ],
  "targeted_insights": [
    {
      "insight": "Identify which content, journey, feedback, progress-visibility, and friction factors are most associated with sustained learning and completion.",
      "linked_objectives": [
        "Measure recent learning frequency, course progress, completion status, and stopping points among current and former LearnSphere learners to identify where engagement pauses or ends.",
        "Measure journey-stage experience and friction from discovery and onboarding through course participation, progress tracking, interruption, and resumption.",
        "Measure content relevance and the usefulness of instructional formats such as videos, quizzes, practice, plans, dashboards, and reminders."
      ],
      "decision_impact": "Set product and learning-design priorities most likely to improve sustained progress and completion."
    },
    {
      "insight": "Segment inactivity into content-led, time-led, motivation-led, technology-led, navigation-led, value-led, trust-led, and competition-led profiles.",
      "linked_objectives": [
        "Measure primary and secondary engagement barriers, including content, time, motivation, navigation, technology, value, trust, and competition barriers.",
        "Measure continuation, return, trial, win-back, and recommendation intent across relevant lifecycle and stakeholder groups."
      ],
      "decision_impact": "Match each segment to an appropriate product fix, content intervention, reminder, offer, or win-back campaign."
    },
    {
      "insight": "Determine whether personalised tools and engagement mechanisms create momentum only when learners notice, understand, trust, and value them.",
      "linked_objectives": [
        "Measure awareness and perceived value of AI recommendations, adaptive learning, feedback, reminders, progress visibility, social learning, and gamification among respondents with relevant exposure."
      ],
      "decision_impact": "Decide whether to improve capability, explainability, onboarding, visibility, trust messaging, social features, or gamification."
    },
    {
      "insight": "Map the alternatives competing for learning time and identify the routes most associated with switching or non-completion.",
      "linked_objectives": [
        "Measure usage of competing platforms, offline alternatives, creator-led content, coaching, institutional systems, and peer-learning routes, including their share of learning time."
      ],
      "decision_impact": "Refine positioning, differentiation, retention strategy, and competitive response."
    },
    {
      "insight": "Compare continuation, return, trial, recommendation, and success criteria across current learners, former learners, potential users, parents, educators, and administrators.",
      "linked_objectives": [
        "Measure continuation, return, trial, win-back, and recommendation intent across relevant lifecycle and stakeholder groups.",
        "Measure role-specific success criteria and evidence requirements among parents or guardians, teachers or instructors, and academic administrators."
      ],
      "decision_impact": "Create separate learner, household, acquisition, educator, and institutional strategies rather than relying on one blended score."
    },
    {
      "insight": "Produce a prioritised improvement roadmap and identify unmet needs that predefined measures do not capture.",
      "linked_objectives": [
        "Prioritise the improvement area most likely to increase engagement, completion, return usage, and recommendation, with a conditional forced-trade-off or MaxDiff exercise if a validated feature list is supplied.",
        "Measure likelihood to recommend and the most important improvement respondents want LearnSphere to make."
      ],
      "decision_impact": "Allocate next-release investment toward improvements with the strongest stated or relative value."
    },
    {
      "insight": "Identify the evidence gaps that must be addressed before certification or institutional-partnership expansion.",
      "linked_objectives": [
        "Measure role-specific success criteria and evidence requirements among parents or guardians, teachers or instructors, and academic administrators."
      ],
      "decision_impact": "Decide whether to proceed with expansion or first invest in outcomes evidence, safety, monitoring, reporting, implementation, and institutional support."
    }
  ],
  "respondent_segments": [
    {
      "key": "current_learner",
      "definition": "A respondent who currently uses LearnSphere and reports recent platform activity.",
      "qualification_rule": "LEARNER_STATUS = \"Current LearnSphere learner\" and RECENT_LEARNSPHERE_ACTIVITY = \"Yes\".",
      "expected_path": "Hook, Usage & Behavior, Attitude & Motivation, CX/Satisfaction, Competitive, Future Intent, and close."
    },
    {
      "key": "former_inactive_learner",
      "definition": "A respondent who previously used LearnSphere but has stopped using it or failed to complete a course.",
      "qualification_rule": "LEARNER_STATUS = \"Former or inactive LearnSphere learner\" and LEARNER_EXPERIENCE_ELIGIBILITY = \"Yes\".",
      "expected_path": "Hook, Usage & Behavior, Attitude & Motivation, CX/Satisfaction, Competitive, win-back branch, Future Intent, and close."
    },
    {
      "key": "potential_user",
      "definition": "A respondent with a relevant learning need who does not currently use LearnSphere and has used an alternative learning route.",
      "qualification_rule": "LEARNER_STATUS = \"Potential digital-learning user\" and RELEVANT_LEARNING_NEED = \"Yes\" and ALTERNATIVE_LEARNING_USE = \"Yes\".",
      "expected_path": "Hook, Usage context, Attitude & Motivation, Competitive, trial branch, Future Intent, and close."
    },
    {
      "key": "parent_guardian",
      "definition": "A parent or guardian who influences a learner's education decision, payment, safety, or progress monitoring.",
      "qualification_rule": "STAKEHOLDER_ROLE includes \"Parent or guardian\".",
      "expected_path": "Hook, applicable Usage context, role-specific success criteria, Future Intent, and close."
    },
    {
      "key": "teacher_instructor",
      "definition": "A teacher or instructor involved in learning delivery, curriculum, learner support, or progress monitoring.",
      "qualification_rule": "STAKEHOLDER_ROLE includes \"Teacher or instructor\".",
      "expected_path": "Hook, applicable Usage context, role-specific success criteria, Future Intent, and close."
    },
    {
      "key": "academic_administrator",
      "definition": "An academic administrator involved in institutional learning decisions, implementation, monitoring, or partnership evaluation.",
      "qualification_rule": "STAKEHOLDER_ROLE includes \"Academic administrator\".",
      "expected_path": "Hook, applicable Usage context, role-specific success criteria, Future Intent, and close."
    }
  ],
  "questionnaire_sections": [
    {
      "key": "hook_warm_up_and_screening",
      "purpose": "Establish stakeholder role, LearnSphere relationship, relevant experience, recent activity, and potential-user eligibility. Supports lifecycle segmentation and early screen-out decisions.",
      "question_keys": [
        "STAKEHOLDER_ROLE",
        "LEARNER_STATUS",
        "LEARNER_EXPERIENCE_ELIGIBILITY",
        "RECENT_LEARNSPHERE_ACTIVITY",
        "RELEVANT_LEARNING_NEED"
      ]
    },
    {
      "key": "usage_and_behavior",
      "purpose": "Measure recent learning behaviour, progress, stopping points, and alternative learning use before asking evaluative questions. Supports engagement, completion, churn, and competitive objectives.",
      "question_keys": [
        "LEARNING_FREQUENCY",
        "COURSE_PROGRESS_STATUS",
        "LEARNING_STOP_POINT",
        "ALTERNATIVE_LEARNING_USE",
        "ALTERNATIVE_PLATFORMS_USED"
      ]
    },
    {
      "key": "attitude_and_motivation",
      "purpose": "Measure content relevance, instructional-format usage and usefulness, and barriers to engagement. Supports content, format, motivation, and churn objectives.",
      "question_keys": [
        "CONTENT_RELEVANCE",
        "LEARNING_FORMATS_USED",
        "LEARNING_FORMAT_USEFULNESS",
        "ENGAGEMENT_BARRIERS"
      ]
    },
    {
      "key": "cx_satisfaction",
      "purpose": "Diagnose journey-stage experience, friction, support-feature exposure and value, overall learner experience, and stakeholder-specific success requirements. Supports experience, feature, trust, and expansion-readiness objectives.",
      "question_keys": [
        "JOURNEY_STAGE_EXPERIENCE",
        "LEARNING_FRICTION",
        "SUPPORT_FEATURES_NOTICED",
        "FEEDBACK_AND_PROGRESS_VALUE",
        "LEARNER_EXPERIENCE_SATISFACTION",
        "ROLE_SPECIFIC_SUCCESS_CRITERIA"
      ]
    },
    {
      "key": "competitive",
      "purpose": "Quantify learning-time allocation across alternatives and capture comparative competitive pressure. Supports competitor, switching, and positioning objectives.",
      "question_keys": [
        "ALTERNATIVE_SHARE_OF_LEARNING_TIME"
      ]
    },
    {
      "key": "future_intent",
      "purpose": "Capture lifecycle-specific continuation, return, trial, and win-back intent; advocacy; and roadmap prioritisation. Supports retention, acquisition, recommendation, and product-investment objectives.",
      "question_keys": [
        "LIFECYCLE_INTENT_AND_WINBACK",
        "NPS_RECOMMENDATION",
        "IMPROVEMENT_PRIORITY",
        "MOST_IMPORTANT_IMPROVEMENT"
      ]
    }
  ],
  "business_rules": [
    {
      "id": "BR1",
      "plain_english": "Ask stakeholder role and LearnSphere relationship before experience questions. Do not collect age, gender, city, residence, NCCS, income, or other database-targeting variables because these are supplied by the audience system."
    },
    {
      "id": "BR2",
      "plain_english": "Terminate respondents who cannot demonstrate sufficient LearnSphere or comparable digital-learning experience for the path selected."
    },
    {
      "id": "BR3",
      "plain_english": "Route current learners to the current path, former or inactive learners to the churn and win-back path, and potential users to the trial-barrier path."
    },
    {
      "id": "BR4",
      "plain_english": "Potential users must report both a relevant learning need and experience with at least one alternative learning route; otherwise terminate."
    },
    {
      "id": "BR5",
      "plain_english": "Role-specific success criteria must be shown using wording and response options appropriate to the selected stakeholder role. Multi-role respondents may answer the applicable role perspectives, but results must remain separately tagged."
    },
    {
      "id": "BR6",
      "plain_english": "Only show format usefulness, support-feature value, journey experience, and learner-experience satisfaction to respondents with relevant experience."
    },
    {
      "id": "BR7",
      "plain_english": "Former or inactive learners receive stopping-point and win-back diagnostics; current learners receive continuation and progress diagnostics; potential users receive trial and proof-point diagnostics."
    },
    {
      "id": "BR8",
      "plain_english": "Use behavioural and usage measures before attitudes, satisfaction, and intent. Use recency anchors and last-active-stage reconstruction to reduce recall ambiguity."
    },
    {
      "id": "BR9",
      "plain_english": "Use a shared barrier measure to classify content, time, motivation, navigation, technology, value, trust, and competition causes without adding an unbudgeted diagnostic battery."
    },
    {
      "id": "BR10",
      "plain_english": "If at least five validated candidate improvements are supplied, show the optional forced-trade-off or MaxDiff task after IMPROVEMENT_PRIORITY; otherwise skip it and do not invent candidate options."
    },
    {
      "id": "BR11",
      "plain_english": "Embed attention checks, speeder detection, straight-line detection, and open-ended quality checks. Failed quality controls terminate as quality failures, not as ordinary eligibility screen-outs."
    },
    {
      "id": "BR12",
      "plain_english": "After the final applicable improvement response, complete the respondent."
    }
  ],
  "dynamic_lists": [
    {
      "id": "DL1",
      "source_question_key": "ALTERNATIVE_PLATFORMS_USED",
      "target_question_key": "ALTERNATIVE_SHARE_OF_LEARNING_TIME",
      "mode": "selected",
      "purpose": "Carry forward only the learning alternatives selected by the respondent so learning-time allocation is measured across routes actually used."
    },
    {
      "id": "DL2",
      "source_question_key": "LEARNING_FORMATS_USED",
      "target_question_key": "LEARNING_FORMAT_USEFULNESS",
      "mode": "selected",
      "purpose": "Rate only instructional formats the respondent reports using, avoiding ratings of unfamiliar formats."
    }
  ],
  "branch_blocks": [
    {
      "id": "BB1",
      "source_question_key": "LEARNER_STATUS",
      "selection_mode": "single",
      "blocks": [
        {
          "option_label": "Current LearnSphere learner",
          "member_question_keys": [
            "COURSE_PROGRESS_STATUS"
          ]
        },
        {
          "option_label": "Former or inactive LearnSphere learner",
          "member_question_keys": [
            "LEARNING_STOP_POINT"
          ]
        },
        {
          "option_label": "Potential digital-learning user",
          "member_question_keys": [
            "ALTERNATIVE_LEARNING_USE"
          ]
        }
      ],
      "rejoin_question_key": "ALTERNATIVE_PLATFORMS_USED"
    },
    {
      "id": "BB2",
      "source_question_key": "LEARNER_STATUS",
      "selection_mode": "single",
      "blocks": [
        {
          "option_label": "Current LearnSphere learner",
          "member_question_keys": [
            "LIFECYCLE_INTENT_AND_WINBACK"
          ]
        },
        {
          "option_label": "Former or inactive LearnSphere learner",
          "member_question_keys": [
            "LIFECYCLE_INTENT_AND_WINBACK"
          ]
        },
        {
          "option_label": "Potential digital-learning user",
          "member_question_keys": [
            "LIFECYCLE_INTENT_AND_WINBACK"
          ]
        }
      ],
      "rejoin_question_key": "NPS_RECOMMENDATION"
    }
  ],
  "termination_and_completion_policy": [
    {
      "condition": "Respondent fails the audience-system eligibility requirements or cannot confirm the required Indian adult audience status.",
      "outcome": "terminate"
    },
    {
      "condition": "LEARNER_EXPERIENCE_ELIGIBILITY indicates no sufficient LearnSphere or comparable digital-learning experience.",
      "outcome": "terminate"
    },
    {
      "condition": "A potential user reports no relevant learning need or no alternative learning-route experience.",
      "outcome": "terminate"
    },
    {
      "condition": "An embedded attention, speed, straight-line, or open-ended quality control fails.",
      "outcome": "terminate"
    },
    {
      "condition": "A question does not apply because the respondent has not used the relevant format, feature, platform, or learning route.",
      "outcome": "skip"
    },
    {
      "condition": "The optional MaxDiff or forced-trade-off prerequisite list contains fewer than five validated improvement options.",
      "outcome": "skip"
    },
    {
      "condition": "The respondent completes the final applicable improvement-priority and open-ended improvement responses.",
      "outcome": "complete"
    }
  ],
  "question_generation_instructions": [
    "METHODOLOGY: Mixed Methodology - Multi-Objective Research Design. Use exactly 25 respondent-facing question keys, a linear modular structure, and a three-phase macro: Hook/screening 15-20%, Core behavioural and diagnostic modules 60-70%, and Close/future intent 15-20%. There are no discrete stimulus cells.",
    "Preserve the section order: Hook and screening, Usage & Behavior, Attitude & Motivation, CX/Satisfaction, Competitive, and Future Intent/close.",
    "Use behavioural measures before attitudes, satisfaction, and intent. Use recency anchors, last-active-stage reconstruction, friction surfacing, hypothetical win-back framing, and final open-ended improvement capture so at least 25% of flow keys use advanced techniques.",
    "Maintain separate lifecycle and stakeholder analysis for current learners, former/inactive learners, potential users, parents or guardians, teachers/instructors, and academic administrators.",
    "Do not generate age, gender, city, residence, NCCS, income, education, or other database-known targeting questions.",
    "For potential users, measure learning need, alternatives, barriers, proof requirements, and trial intent without asking them to evaluate unexperienced LearnSphere features.",
    "For former learners, use LIFECYCLE_INTENT_AND_WINBACK to capture return likelihood, recoverability, switching cost, and the intervention most likely to bring them back.",
    "For current learners, use LIFECYCLE_INTENT_AND_WINBACK to capture continuation and return intent. For potential users, use it to capture trial intent.",
    "Use dynamic lists only where the target preserves the source option text and order: alternatives to learning-time allocation and used formats to format usefulness.",
    "Use compact, mobile-friendly measures and avoid long agree/disagree grids. Interleave behavioural, rating, forced-choice, and open-ended formats.",
    "Show MaxDiff or Best-Worst Scaling only when a validated list of at least five candidate improvements is supplied; otherwise use the single improvement-priority measure and do not invent options.",
    "Include quality controls at the specified ratio without creating additional questionnaire keys or sections."
  ],
  "analysis_tags": [
    "stakeholder_role",
    "learnsphere_relationship",
    "current_vs_former_vs_potential",
    "recent_activity",
    "learning_frequency",
    "course_completion_stage",
    "learning_stop_point",
    "content_relevance",
    "instructional_format_usage",
    "instructional_format_usefulness",
    "journey_stage_friction",
    "technical_friction",
    "navigation_friction",
    "time_scheduling_barrier",
    "motivation_barrier",
    "value_barrier",
    "trust_barrier",
    "competitive_barrier",
    "feedback_usefulness",
    "progress_visibility",
    "adaptive_tool_awareness",
    "adaptive_tool_trust",
    "adaptive_tool_usefulness",
    "social_learning_value",
    "gamification_value",
    "alternative_platform_usage",
    "alternative_share_of_learning_time",
    "switching_cost",
    "winback_potential",
    "continue_intent",
    "return_intent",
    "trial_intent",
    "recommendation_intent",
    "nps",
    "parent_success_criteria",
    "educator_success_criteria",
    "administrator_success_criteria",
    "institutional_readiness",
    "feature_priority",
    "maxdiff_utility",
    "open_end_theme",
    "quality_status"
  ],
  "assumptions": [
    "The 25-question budget applies across all declared questionnaire sections and includes conditional branch keys only once.",
    "Role-specific stakeholder success criteria are captured through one shared flow key with role-appropriate display and response content.",
    "The final stakeholder routing may permit multiple role tags, but analysis must keep learner, household, educator, and administrator perspectives separate.",
    "Age, India residence, city, gender, NCCS, and quotas are enforced by the audience system and are not recaptured.",
    "The MaxDiff task remains conditional because no validated candidate-improvement list was supplied."
  ],
  "ambiguities": [
    "The exact recency window defining current versus former/inactive LearnSphere use is not specified.",
    "The exact option labels for LEARNER_EXPERIENCE_ELIGIBILITY, RELEVANT_LEARNING_NEED, and ALTERNATIVE_LEARNING_USE must be confirmed before scripting termination rules.",
    "The brief describes overlapping stakeholder quotas but does not confirm whether multi-role respondents should answer one primary role module or multiple role perspectives.",
    "The candidate improvement list required for MaxDiff has not been supplied."
  ]
}

